// A simple class for demonstration.
class Widget {
public:
    Widget() { std::cout << "Widget created\n"; }
    ~Widget() { std::cout << "Widget destroyed\n"; }
};

// 1. Basic exclusive ownership within a scope.
{
    std::unique_ptr<Widget> u_ptr1(new Widget());
    // u_ptr1 owns the Widget.
} // Widget is automatically destroyed here.

// 2. Move-only semantics prevent copying.
auto u_ptr2 = std::make_unique<Widget>();
// std::unique_ptr<Widget> u_ptr3 = u_ptr2; // Compile Error: Copying is disabled.
std::unique_ptr<Widget> u_ptr4 = std::move(u_ptr2); // OK: Ownership is transferred.
// u_ptr2 is now nullptr.

// 3. Resetting the pointer destroys the managed object.
u_ptr4.reset(); // The second Widget is destroyed here.
std::cout << "End of main\n";
